// What is typed into cells, in the editor: data validation (refused values,
// warnings, the list a cell offers, the message beside it), formulas typed the
// Turkish way, and the mark on formulas the engine cannot calculate. Every
// workbook is generated by code and kept within columns A to D of the first
// rows, so that a phone shows it as well.
//
// Canvas positions are written out from the default sizes of a sheet: the row
// numbers are 72 px wide, the column letters 22 px high, columns 64 px wide
// and rows 20 px high.
import type { Page } from '@playwright/test';
import { buildXlsx, worksheetXml } from '../test/fixtures';
import { expect, test } from './helpers';

const HEADER_WIDTH = 72;
const HEADER_HEIGHT = 22;
const COLUMN_WIDTH = 64;
const ROW_HEIGHT = 20;

const num = (ref: string, value: number) => `<c r="${ref}"><v>${value}</v></c>`;
const str = (ref: string, text: string) => `<c r="${ref}" t="inlineStr"><is><t>${text}</t></is></c>`;
const formula = (ref: string, text: string, value: number) => `<c r="${ref}"><f>${text}</f><v>${value}</v></c>`;
const dv = (attrs: string, inner = '') => `<dataValidation ${attrs}>${inner}</dataValidation>`;

function once<T>(make: () => Promise<T>): () => Promise<T> {
  let value: Promise<T> | undefined;
  return () => (value ??= make());
}

/**
 * "Check": A2:A9 whole numbers 1 to 10 (stops, with a message of its own);
 * B2:B9 a list written into the rule, with an input message; C2:C9 a list
 * from a range on the sheet "Lists" (only warns); D2:D9 a custom formula
 * without messages; A12 a list that hides its button.
 * "Lists": Red, Green, Blue.
 * "Calc": A1 = 1, B1 = A1*2, C1 a function the engine does not have (the file
 * says 7), D1 and A2 refer to each other.
 */
const checkWorkbook = once(() =>
  buildXlsx({
    sheets: [
      {
        name: 'Check',
        xml: worksheetXml(
          `<sheetData><row r="1">${str('A1', 'Qty')}${str('B1', 'Answer')}${str('C1', 'Colour')}${str('D1', 'Number')}</row>` +
            `<row r="2">${num('A2', 3)}${str('C2', 'Green')}</row><row r="3">${num('A3', 4)}</row></sheetData>` +
            '<dataValidations count="5">' +
            dv('type="whole" allowBlank="1" showErrorMessage="1" errorTitle="Quantity" error="Enter 1 to 10" sqref="A2:A9"', '<formula1>1</formula1><formula2>10</formula2>') +
            dv('type="list" allowBlank="1" showInputMessage="1" showErrorMessage="1" promptTitle="Answer" prompt="Pick one of the three" sqref="B2:B9"', '<formula1>"Yes,No,Maybe"</formula1>') +
            dv('type="list" allowBlank="1" showErrorMessage="1" errorStyle="warning" error="Unknown colour" sqref="C2:C9"', '<formula1>Lists!$A$1:$A$3</formula1>') +
            dv('type="custom" showErrorMessage="1" sqref="D2:D9"', '<formula1>ISNUMBER(D2)</formula1>') +
            dv('type="list" showDropDown="1" showErrorMessage="1" sqref="A12"', '<formula1>"a,b"</formula1>') +
            '</dataValidations>',
        ),
      },
      { name: 'Lists', xml: worksheetXml(`<sheetData><row r="1">${str('A1', 'Red')}</row><row r="2">${str('A2', 'Green')}</row><row r="3">${str('A3', 'Blue')}</row></sheetData>`) },
      {
        name: 'Calc',
        xml: worksheetXml(
          `<sheetData><row r="1">${num('A1', 1)}${formula('B1', 'A1*2', 2)}${formula('C1', 'NOSUCHFUNCTION(A1)', 7)}${formula('D1', 'A2+A1', 0)}</row>` +
            `<row r="2">${formula('A2', 'D1+1', 0)}${num('B2', 5)}</row></sheetData>`,
        ),
      },
    ],
  }),
);

async function mount(page: Page, bytes: Uint8Array, options: Record<string, unknown> = {}): Promise<void> {
  await page.goto('/e2e/pages/editor.html');
  await page.waitForFunction(() => typeof (window as any).__mountEditor === 'function');
  await page.evaluate(
    async ({ base64, options }) => {
      const text = atob(base64);
      const data = new Uint8Array(text.length);
      for (let i = 0; i < text.length; i++) data[i] = text.charCodeAt(i);
      await (window as any).__mountEditor(data, options, 'host');
    },
    { base64: Buffer.from(bytes).toString('base64'), options: { locale: 'en-US', ...options } },
  );
}

const select = (page: Page, ref: string) =>
  page.evaluate((ref) => {
    const api = (window as any).BymOffice;
    const view = (window as any).__editor.view;
    view.select(api.parseRange(ref));
    view.focus();
  }, ref);

const settled = (page: Page) => page.evaluate(() => new Promise<void>((resolve) => requestAnimationFrame(() => requestAnimationFrame(() => resolve()))));

interface CellInfo {
  value: number | string | boolean | null;
  formula: string | null;
}

const cell = (page: Page, ref: string, sheet = 0): Promise<CellInfo> =>
  page.evaluate(
    ([ref, sheet]) => {
      const api = (window as any).BymOffice;
      const at = api.parseCellRef(ref);
      const found = api.getCell((window as any).__editor.view.workbook.sheets[sheet as number], at.row, at.col);
      return found ? { value: found.value, formula: found.formula ? found.formula.text : null } : { value: null, formula: null };
    },
    [ref, sheet] as [string, number],
  );

/** Types into the active cell and presses Enter. */
async function typeIn(page: Page, ref: string, text: string): Promise<void> {
  await select(page, ref);
  await page.keyboard.type(text);
  await page.keyboard.press('Enter');
}

const editing = (page: Page) => page.evaluate(() => (window as any).__editor.view.isEditing as boolean);
const message = (page: Page) => page.locator('#host .bym-status-message');
const dropdown = (page: Page) => page.locator('#host .bym-dropdown');
const tip = (page: Page) => page.locator('#host .bym-tip');
const selection = (page: Page) => page.evaluate(() => (window as any).BymOffice.rangeName((window as any).__editor.view.selection.range));

/** Colour of one canvas pixel (CSS coordinates relative to the canvas) after a forced redraw. */
function pixel(page: Page, x: number, y: number): Promise<number[]> {
  return page.evaluate(
    ([x, y]) => {
      const view = (window as any).__editor.view;
      view.render();
      const element = document.querySelector('#host .bym-canvas') as HTMLCanvasElement;
      const dpr = view.getViewState().devicePixelRatio;
      return Array.from(element.getContext('2d')!.getImageData(Math.round(x * dpr), Math.round(y * dpr), 1, 1).data).slice(0, 3);
    },
    [x, y],
  );
}

/** The middle of the list button of a cell (column 0 is A, row 1 is the first row). */
const buttonOf = (col: number, row: number) => ({ x: HEADER_WIDTH + COLUMN_WIDTH * (col + 1) - 9, y: HEADER_HEIGHT + ROW_HEIGHT * row - 9 });
/** A pixel of the left border of that button (see filter.spec.ts for the 0.3). */
const borderPixel = (page: Page, col: number, row: number) => pixel(page, buttonOf(col, row).x - 7.7, buttonOf(col, row).y);
const BORDER = [154, 160, 166];

async function pressAt(page: Page, hasTouch: boolean | undefined, x: number, y: number): Promise<void> {
  const box = (await page.locator('#host .bym-canvas').boundingBox())!;
  if (hasTouch) await page.touchscreen.tap(box.x + x, box.y + y);
  else await page.mouse.click(box.x + x, box.y + y);
}

test.describe('data validation', () => {
  test('a value a rule stops is not written: the editor stays open and the rule says why', async ({ page }) => {
    await mount(page, await checkWorkbook());
    await typeIn(page, 'A2', '11');
    expect(await editing(page)).toBe(true);
    expect((await cell(page, 'A2')).value).toBe(3);
    await expect(message(page)).toHaveText('Quantity: Enter 1 to 10');
    expect(await selection(page)).toBe('A2');
    // The text that was typed is still there to be corrected.
    expect(await page.evaluate(() => (window as any).__editor.view.editText)).toBe('11');
    await page.keyboard.press('Backspace');
    await page.keyboard.press('Backspace');
    await page.keyboard.type('7');
    await page.keyboard.press('Enter');
    expect(await editing(page)).toBe(false);
    expect((await cell(page, 'A2')).value).toBe(7);
    expect(await selection(page)).toBe('A3');
    // Not a whole number, not a number at all.
    await typeIn(page, 'A3', '2.5');
    expect(await editing(page)).toBe(true);
    await page.keyboard.press('Escape');
    expect((await cell(page, 'A3')).value).toBe(4);
    await typeIn(page, 'A3', 'many');
    expect(await editing(page)).toBe(true);
    await page.keyboard.press('Escape');
    // Outside the rule anything goes; a formula is not checked.
    await typeIn(page, 'A10', '999');
    expect((await cell(page, 'A10')).value).toBe(999);
    await typeIn(page, 'A4', '=50*2');
    expect(await cell(page, 'A4')).toEqual({ value: 100, formula: '50*2' });
    expect(await editing(page)).toBe(false);
  });

  test('a rule without a message of its own says the default, in the language of the view', async ({ page }) => {
    await mount(page, await checkWorkbook());
    await typeIn(page, 'D2', 'text');
    expect(await editing(page)).toBe(true);
    await expect(message(page)).toHaveText('This value does not match the data validation rule of the cell.');
    await page.keyboard.press('Escape');
    // The formula of the rule reads the value being typed: a number passes.
    await typeIn(page, 'D2', '12');
    expect((await cell(page, 'D2')).value).toBe(12);
    // Trying the wrong value out left no trace: one undo step empties the cell again.
    await page.evaluate(() => (window as any).__editor.view.undo());
    expect((await cell(page, 'D2')).value).toBe(null);
    expect(await page.evaluate(() => (window as any).__editor.view.undo())).toBe(false);

    await mount(page, await checkWorkbook(), { locale: 'tr' });
    await typeIn(page, 'D2', 'metin');
    expect(await editing(page)).toBe(true);
    await expect(message(page)).toHaveText('Bu değer hücrenin veri doğrulama kuralına uymuyor.');
  });

  test('a rule that only warns writes the value and says so', async ({ page }) => {
    await mount(page, await checkWorkbook());
    await typeIn(page, 'C3', 'Pink');
    expect(await editing(page)).toBe(false);
    expect((await cell(page, 'C3')).value).toBe('Pink');
    await expect(message(page)).toHaveText('Unknown colour (the value was entered anyway)');
    // A value of the list on the other sheet passes without a word, whatever its case.
    await typeIn(page, 'C4', 'blue');
    expect((await cell(page, 'C4')).value).toBe('blue');
    await settled(page);
    await expect(message(page)).toHaveText('');
  });

  test('pasting does not ask the rules, as in Excel', async ({ page }) => {
    await mount(page, await checkWorkbook());
    await select(page, 'A2');
    await page.evaluate(() => (window as any).__editor.view.paste('99'));
    expect((await cell(page, 'A2')).value).toBe(99);
  });

  test('a list cell shows a button and its message; the list writes the chosen value as one undo step', async ({ page, hasTouch }) => {
    await mount(page, await checkWorkbook());
    await select(page, 'A2');
    await settled(page);
    expect(await borderPixel(page, 1, 2)).toEqual([255, 255, 255]);
    await expect(tip(page)).toHaveCount(0);

    await select(page, 'B2');
    await settled(page);
    expect(await borderPixel(page, 1, 2)).toEqual(BORDER);
    await expect(tip(page)).toBeVisible();
    await expect(tip(page).locator('.bym-tip-title')).toHaveText('Answer');
    await expect(tip(page).locator('.bym-tip-text')).toHaveText('Pick one of the three');
    // The same words reach assistive technology.
    await expect(page.locator('#host .bym-live')).toHaveText('B2. Answer: Pick one of the three');
    // The note is beside the cell, inside the view, and never takes a press.
    const note = (await tip(page).boundingBox())!;
    const view = (await page.locator('#host .bym-view').boundingBox())!;
    expect(note.x).toBeGreaterThanOrEqual(view.x);
    expect(note.x + note.width).toBeLessThanOrEqual(view.x + view.width + 0.5);
    expect(await tip(page).evaluate((element) => getComputedStyle(element).pointerEvents)).toBe('none');

    const at = buttonOf(1, 2);
    await pressAt(page, hasTouch, at.x, at.y);
    await expect(dropdown(page)).toBeVisible();
    await expect(dropdown(page)).toHaveAttribute('aria-label', 'Choose from the list');
    expect(await dropdown(page).locator('.bym-list-row').allTextContents()).toEqual(['Yes', 'No', 'Maybe']);
    // The note makes room for the list.
    await expect(tip(page)).toHaveCount(0);
    const row = dropdown(page).locator('.bym-list-row', { hasText: 'No' });
    await (hasTouch ? row.tap() : row.click());
    await expect(dropdown(page)).toHaveCount(0);
    expect((await cell(page, 'B2')).value).toBe('No');
    expect(await selection(page)).toBe('B2');
    expect(await page.evaluate(() => document.activeElement!.className)).toBe('bym-input');
    await expect(tip(page)).toBeVisible();

    // The list knows what the cell holds.
    await pressAt(page, hasTouch, at.x, at.y);
    await expect(dropdown(page).locator('.bym-list-row[aria-selected="true"]')).toHaveText('No');
    await page.keyboard.press('Escape');
    await expect(dropdown(page)).toHaveCount(0);
    expect((await cell(page, 'B2')).value).toBe('No');

    await page.evaluate(() => (window as any).__editor.view.undo());
    expect((await cell(page, 'B2')).value).toBe(null);
    // Typing something that is not in the list is refused.
    await typeIn(page, 'B3', 'Perhaps');
    expect(await editing(page)).toBe(true);
  });

  test('Alt+Down opens the list; arrows and Enter choose from a list that lives on another sheet', async ({ page }) => {
    await mount(page, await checkWorkbook());
    await select(page, 'C2');
    await page.keyboard.press('Alt+ArrowDown');
    await expect(dropdown(page)).toBeVisible();
    const list = dropdown(page).locator('.bym-list');
    await expect(list).toBeFocused();
    expect(await dropdown(page).locator('.bym-list-row').allTextContents()).toEqual(['Red', 'Green', 'Blue']);
    // The row of the value the cell holds is the active one.
    await expect(dropdown(page).locator('.bym-list-row[data-active]')).toHaveText('Green');
    await page.keyboard.press('ArrowDown');
    await page.keyboard.press('Enter');
    await expect(dropdown(page)).toHaveCount(0);
    expect((await cell(page, 'C2')).value).toBe('Blue');
    expect(await page.evaluate(() => document.activeElement!.className)).toBe('bym-input');

    // A press elsewhere closes the list and changes nothing.
    await page.keyboard.press('Alt+ArrowDown');
    await expect(dropdown(page)).toBeVisible();
    await page.locator('#after').click();
    await expect(dropdown(page)).toHaveCount(0);
    expect((await cell(page, 'C2')).value).toBe('Blue');

    // A list that hides its button has none, and no key opens it; the rule still applies.
    await select(page, 'A12');
    await settled(page);
    expect(await borderPixel(page, 0, 12)).toEqual([255, 255, 255]);
    await page.keyboard.press('Alt+ArrowDown');
    await expect(dropdown(page)).toHaveCount(0);
    await typeIn(page, 'A12', 'c');
    expect(await editing(page)).toBe(true);
    await page.keyboard.press('Escape');
    await typeIn(page, 'A12', 'b');
    expect((await cell(page, 'A12')).value).toBe('b');
  });

  test('read-only: no list button and no list, the message is still shown', async ({ page, hasTouch }) => {
    await mount(page, await checkWorkbook(), { readOnly: true });
    await select(page, 'B2');
    await settled(page);
    expect(await borderPixel(page, 1, 2)).toEqual([255, 255, 255]);
    await expect(tip(page)).toBeVisible();
    const at = buttonOf(1, 2);
    await pressAt(page, hasTouch, at.x, at.y);
    await expect(dropdown(page)).toHaveCount(0);
    expect(await page.evaluate(() => (window as any).__editor.view.openValidationList())).toBe(false);
  });
});

/**
 * "Dep": A2 may hold what keeps A3 (= A2 * 2) at 100 or less; B2 has a rule whose formula
 * uses a function the engine does not have; C2 takes whole numbers 1 to 10; D2 a rule whose
 * formula gives an error.
 */
const dependentWorkbook = once(() =>
  buildXlsx({
    sheets: [
      {
        name: 'Dep',
        xml: worksheetXml(
          `<sheetData><row r="1">${str('A1', 'Half')}${str('B1', 'Free')}${str('C1', 'Whole')}${str('D1', 'Never')}</row>` +
            `<row r="2">${num('A2', 1)}</row><row r="3">${formula('A3', 'A2*2', 2)}</row></sheetData>` +
            '<dataValidations count="4">' +
            dv('type="custom" showErrorMessage="1" error="Twice this must not pass 100" sqref="A2"', '<formula1>$A$3&lt;=100</formula1>') +
            dv('type="custom" showErrorMessage="1" sqref="B2"', '<formula1>NOSUCHFUNCTION(B2)</formula1>') +
            dv('type="whole" showErrorMessage="1" sqref="C2"', '<formula1>1</formula1><formula2>10</formula2>') +
            dv('type="custom" showErrorMessage="1" sqref="D2"', '<formula1>1/0</formula1>') +
            '</dataValidations>',
        ),
      },
    ],
  }),
);

test.describe('a value that is tried out', () => {
  const changes = (page: Page) => page.evaluate(() => (window as any).__events.filter((event: any) => event.type === 'change').length);

  test('a custom rule judges the formulas that depend on what is typed, and a refused value does not lock the cell', async ({ page }) => {
    await mount(page, await dependentWorkbook());
    // 60 would make A3 120.
    await typeIn(page, 'A2', '60');
    expect(await editing(page)).toBe(true);
    await expect(message(page)).toHaveText('Twice this must not pass 100');
    expect((await cell(page, 'A2')).value).toBe(1);
    expect((await cell(page, 'A3')).value).toBe(2);
    // Nothing of the attempt was reported or kept.
    expect(await changes(page)).toBe(0);
    expect(await page.evaluate(() => (window as any).__editor.view.history.canUndo)).toBe(false);
    await page.keyboard.press('Escape');
    // 10 is fine, whatever was refused before it.
    await typeIn(page, 'A2', '10');
    expect(await editing(page)).toBe(false);
    expect((await cell(page, 'A2')).value).toBe(10);
    expect((await cell(page, 'A3')).value).toBe(20);
    expect(await changes(page)).toBe(1);
    await typeIn(page, 'A2', '51');
    expect(await editing(page)).toBe(true);
    await page.keyboard.press('Escape');
    await typeIn(page, 'A2', '50');
    expect(await editing(page)).toBe(false);
    expect((await cell(page, 'A3')).value).toBe(100);
    // Two steps were written, and only those.
    await page.evaluate(() => (window as any).__editor.view.undo());
    await page.evaluate(() => (window as any).__editor.view.undo());
    expect((await cell(page, 'A3')).value).toBe(2);
    expect(await page.evaluate(() => (window as any).__editor.view.history.canUndo)).toBe(false);
  });

  test('a rule the engine cannot calculate is not applied; one whose formula gives an error refuses', async ({ page }) => {
    await mount(page, await dependentWorkbook());
    await typeIn(page, 'B2', 'anything');
    expect(await editing(page)).toBe(false);
    expect((await cell(page, 'B2')).value).toBe('anything');
    await typeIn(page, 'D2', '5');
    expect(await editing(page)).toBe(true);
    await page.keyboard.press('Escape');
    expect((await cell(page, 'D2')).value).toBe(null);
  });

  test('refused values leave the file byte for byte what it was', async ({ page }) => {
    const bytes = await dependentWorkbook();
    await mount(page, bytes);
    const state = () =>
      page.evaluate(async () => {
        const workbook = (window as any).__editor.view.workbook;
        return {
          formats: workbook.styles.cellXfs.length,
          numFmts: workbook.styles.numFmts.size,
          stylesModified: workbook.styles.modified,
          modified: workbook.sheets[0].modified,
          saved: Array.from((await (window as any).__file.save()) as Uint8Array),
        };
      });
    const before = await state();
    expect(before.saved).toEqual(Array.from(bytes));
    // A date asks for a date format before the rule refuses it; a tried value recalculates A3.
    await typeIn(page, 'C2', '2/1/2024');
    expect(await editing(page)).toBe(true);
    await page.keyboard.press('Escape');
    await typeIn(page, 'A2', '60');
    expect(await editing(page)).toBe(true);
    await page.keyboard.press('Escape');
    await typeIn(page, 'C2', '50%');
    expect(await editing(page)).toBe(true);
    await page.keyboard.press('Escape');
    expect(await state()).toEqual(before);
  });
});

test.describe('formulas typed the Turkish way', () => {
  test('";" between arguments, "," in numbers and Turkish function names are stored the way files have them', async ({ page }) => {
    await mount(page, await checkWorkbook(), { locale: 'tr' });
    await typeIn(page, 'D12', '=TOPLA(A2;A3)*1,5');
    expect(await cell(page, 'D12')).toEqual({ value: 10.5, formula: 'SUM(A2,A3)*1.5' });
    // Shown again the Turkish way, in the cell editor and in the formula bar.
    await select(page, 'D12');
    await settled(page);
    await expect(page.locator('#host .bym-formula-input')).toHaveValue('=SUM(A2;A3)*1,5');
    await page.keyboard.press('F2');
    expect(await page.evaluate(() => (window as any).__editor.view.editText)).toBe('=SUM(A2;A3)*1,5');
    // Left as it is, nothing is written.
    await page.keyboard.press('Enter');
    expect(await page.evaluate(() => (window as any).__editor.view.history.canUndo)).toBe(true);
    await page.evaluate(() => (window as any).__editor.view.undo());
    expect(await page.evaluate(() => (window as any).__editor.view.history.canUndo)).toBe(false);

    await typeIn(page, 'D13', '=EĞER(A2>3,5;"büyük; evet";YUVARLA(A3/3;2))');
    expect(await cell(page, 'D13')).toEqual({ value: 1.33, formula: 'IF(A2>3.5,"büyük; evet",ROUND(A3/3,2))' });
    // English function names are fine; the separators are those of the locale.
    await typeIn(page, 'D14', '=SUM(A2;A3)');
    expect(await cell(page, 'D14')).toEqual({ value: 7, formula: 'SUM(A2,A3)' });
  });

  test('a comma that is not a decimal comma is refused: a formula typed the English way never turns into another one', async ({ page }) => {
    await mount(page, await checkWorkbook(), { locale: 'tr' });
    const hint = 'Bu formül okunamadı. Argümanları noktalı virgülle (;) ayırın, ondalıkları virgülle yazın; tanınmayan fonksiyonlarda İngilizce adı kullanın.';
    // "5,1" would be read as the number 5.1, and the formula as IF(A2>5.1,0).
    for (const typed of ['=IF(A2>5,1,0)', '=ROUND(A2,2)', '=SUM(A2,A3)', '=DATE(2024,1,5)']) {
      await typeIn(page, 'D14', typed);
      expect(await editing(page), typed).toBe(true);
      await expect(message(page)).toHaveText(hint);
      expect(await page.evaluate(() => (window as any).__editor.view.editText)).toBe(typed);
      await page.keyboard.press('Escape');
      expect(await cell(page, 'D14')).toEqual({ value: null, formula: null });
    }
    expect(await page.evaluate(() => (window as any).__editor.view.history.canUndo)).toBe(false);
    // Written with ";" the same formula is taken, and "1,5" between digits is a number.
    await typeIn(page, 'D14', '=IF(A2>5;1;0)+1,5');
    expect(await cell(page, 'D14')).toEqual({ value: 1.5, formula: 'IF(A2>5,1,0)+1.5' });
    // Pasted from elsewhere, what cannot be read stays the text it is.
    await select(page, 'D15');
    await page.evaluate(() => (window as any).__editor.view.paste('=IF(A2>5,1,0)'));
    expect(await cell(page, 'D15')).toEqual({ value: '=IF(A2>5,1,0)', formula: null });
    // Turkish names of the error values are read; what is shown is the value of the file.
    await typeIn(page, 'D16', '#YOK');
    expect((await cell(page, 'D16')).value).toBe('#N/A');
  });

  test('a formula that cannot be read is refused with a hint about the separators', async ({ page }) => {
    await mount(page, await checkWorkbook(), { locale: 'tr' });
    await typeIn(page, 'D12', '=TOPLA(A2;;');
    expect(await editing(page)).toBe(true);
    await expect(message(page)).toHaveText('Bu formül okunamadı. Argümanları noktalı virgülle (;) ayırın, ondalıkları virgülle yazın; tanınmayan fonksiyonlarda İngilizce adı kullanın.');
    await page.keyboard.press('Escape');
    expect((await cell(page, 'D12')).formula).toBe(null);
  });

  test('pasted from elsewhere a Turkish formula is translated; in an English view nothing changes', async ({ page }) => {
    await mount(page, await checkWorkbook(), { locale: 'tr' });
    await select(page, 'D12');
    await page.evaluate(() => (window as any).__editor.view.paste('=ORTALAMA(A2;A3)\t1,5'));
    expect(await cell(page, 'D12')).toEqual({ value: 3.5, formula: 'AVERAGE(A2,A3)' });
    expect((await cell(page, 'E12')).value).toBe(1.5);

    await mount(page, await checkWorkbook(), { locale: 'en-US' });
    await typeIn(page, 'D12', '=SUM(A2,A3)*1.5');
    expect(await cell(page, 'D12')).toEqual({ value: 10.5, formula: 'SUM(A2,A3)*1.5' });
    await select(page, 'D12');
    await settled(page);
    await expect(page.locator('#host .bym-formula-input')).toHaveValue('=SUM(A2,A3)*1.5');
    await typeIn(page, 'D13', '=SUM(A2;A3)');
    expect(await editing(page)).toBe(true);
    await expect(message(page)).toHaveText('This formula cannot be read. Use English function names and commas between arguments.');
  });
});

test.describe('formulas that cannot be calculated here', () => {
  /** A point inside the mark in the top left corner of a cell of row 1. */
  const mark = (col: number) => ({ x: HEADER_WIDTH + COLUMN_WIDTH * col + 1.3, y: HEADER_HEIGHT + 1.3 });
  const markPixel = (page: Page, col: number) => pixel(page, mark(col).x, mark(col).y);
  const WHITE = [255, 255, 255];

  test('get a mark once the engine has looked at them, and say what the mark means', async ({ page }) => {
    await mount(page, await checkWorkbook(), { sheet: 2 });
    await settled(page);
    // Nothing was calculated yet: no marks, and nothing is said.
    expect(await markPixel(page, 2)).toEqual(WHITE);
    expect(await markPixel(page, 3)).toEqual(WHITE);
    await select(page, 'C1');
    await settled(page);
    await expect(message(page)).toHaveText('');

    // An edit makes the engine calculate.
    await typeIn(page, 'A1', '5');
    expect((await cell(page, 'B1', 2)).value).toBe(10);
    // The function the engine does not have keeps the value of the file, and is marked.
    expect(await cell(page, 'C1', 2)).toEqual({ value: 7, formula: 'NOSUCHFUNCTION(A1)' });
    expect(await markPixel(page, 2)).toEqual([232, 113, 10]);
    expect(await markPixel(page, 1)).toEqual(WHITE);
    expect(await markPixel(page, 0)).toEqual(WHITE);
    // The two cells that read each other.
    expect(await markPixel(page, 3)).toEqual([217, 48, 37]);

    await select(page, 'C1');
    await settled(page);
    await expect(message(page)).toHaveText('This formula cannot be calculated here; the last value in the file is shown');
    await expect(page.locator('#host .bym-live')).toHaveText('C1 7. This formula cannot be calculated here; the last value in the file is shown');
    await select(page, 'D1');
    await settled(page);
    await expect(message(page)).toHaveText('Circular reference');
    await select(page, 'B1');
    await settled(page);
    await expect(message(page)).toHaveText('');

    // Replacing the formula takes the mark away.
    await typeIn(page, 'C1', '=A1+1');
    expect((await cell(page, 'C1', 2)).value).toBe(6);
    expect(await markPixel(page, 2)).toEqual(WHITE);
    await page.evaluate(() => (window as any).__editor.view.undo());
    expect(await markPixel(page, 2)).toEqual([232, 113, 10]);
  });

  test('speak Turkish with a Turkish locale, and cost nothing when formulas are not calculated', async ({ page }) => {
    await mount(page, await checkWorkbook(), { sheet: 2, locale: 'tr' });
    await typeIn(page, 'A1', '6');
    await select(page, 'C1');
    await settled(page);
    await expect(message(page)).toHaveText('Bu formül burada hesaplanamıyor; dosyadaki son değer gösteriliyor');
    await select(page, 'D1');
    await settled(page);
    await expect(message(page)).toHaveText('Döngüsel başvuru');

    await mount(page, await checkWorkbook(), { sheet: 2, calculate: false });
    await typeIn(page, 'A1', '5');
    expect(await markPixel(page, 2)).toEqual(WHITE);
    await select(page, 'C1');
    await settled(page);
    await expect(message(page)).toHaveText('');
  });
});
